('200008', '200008', '4:30 AM - 9:00 PM', '4:30 AM - 9:00 PM', '4:30 AM - 9:00 PM', '4:30 AM - 9:00 PM', '4:30 AM - 9:00 PM', '4:30 AM - 9:00 PM', '4:30 AM - 9:00 PM', 'Daily. [verified: Bangkok Metropolitan Administration / invest.bangkok.go.th]'),
