INSERT INTO festivals (id, state_id, city_id, place_id, festival_name, timing_label, lunar_note, duration_label, description, source, updated_at) VALUES
(300001, 9001, 2001, NULL, 'Songkran in Bangkok', '13-15 April', 'Solar-calendar national holiday period; local programming varies yearly', '3 days', 'Bangkok-wide Thai New Year water festival and cultural celebrations; exact road closures and event zones should be refreshed annually.', 'own', '2026-10-01 16:22:00'),
(300002, 9001, 2001, NULL, 'Loy Krathong in Bangkok', 'November', 'Full moon of the 12th Thai lunar month; date shifts yearly', '1 evening', 'Krathong-floating celebrations take place at riverfronts, canals, parks and event venues across Bangkok.', 'own', '2026-10-01 16:22:00'),
(300003, 9001, 2001, 200010, 'Chinese New Year in Yaowarat', 'January-February', 'Lunar calendar; date shifts yearly', '1-3 days', 'Yaowarat/Chinatown hosts decorations, performances and celebrations around Lunar New Year.', 'own', '2026-10-01 16:22:00');
INSERT INTO festivals (id, state_id, city_id, place_id, festival_name, timing_label, lunar_note, duration_label, description, source, updated_at) VALUES
(300004, 9002, 2002, NULL, 'Phuket Vegetarian Festival 2026', '10-18 October 2026', 'Observed in the ninth month of the Chinese lunar calendar; dates shift yearly', '9 days', 'Major Phuket faith festival centered on Chinese shrines, vegetarian observance, processions and ritual ceremonies across the province. Refresh dates annually.', 'own', '2026-10-01 16:22:00'),
(300005, 9002, 2002, 200028, 'Phuket Water Festival 2026', '11-13 April 2026', 'Thai New Year / Songkran period', '3 days', '2026 Phuket Water Festival activities included Patong Beach and Wat Mai Khao, combining Songkran traditions, Peranakan culture, art installations and community markets.', 'own', '2026-10-01 16:22:00'),
(300006, 9002, 2002, 200021, 'Feel All the Feelings @ Phuket: Illuminating Peranakan', '23-29 August 2026', '2026 dated event; do not assume annual recurrence without refresh', '7 days', 'Projection-mapping, Khon and jazz program at the Chartered Bank Intersection in Phuket Old Town celebrating Baba-Peranakan heritage.', 'own', '2026-10-01 16:22:00');
INSERT INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score, created_at, google_place_id, category, cuisine, price_band, veg_flag, source, updated_at, verification_status, verification_notes, verified_at) VALUES
('200041', '2003', 'Wat Phra That Doi Suthep', 'Doi Suthep Temple', 'Chiang Mai’s landmark mountain temple, centered on a gilded chedi and reached by a naga staircase with panoramic views over the city.', '2-3 hours', 'Early Morning', 'Go early for cooler weather and lighter crowds; the staircase has more than 300 steps and a tram is available.', '', 'Chiang Mai', 1, 1, '6:15 AM', '6:10 PM', 'Tram THB 20; foreign temple admission commonly reported separately, confirm onsite', 5.0, 4.9, 18.8049, 98.9216, 'Huay Kaew Road, Suthep, Mueang Chiang Mai, Chiang Mai 50300', 'https://thai.tourismthailand.org/Attraction/%25E0%25B8%25A7%25E0%25B8%25B1%25E0%25B8%2594%25E0%25B8%259E%25E0%25B8%25A3%25E0%25B8%25B0%25E0%25B8%2598%25E0%25B8%25B2%25E0%25B8%2595%25E0%25B8%25B8%25E0%25B8%2594%25E0%25B8%25AD%25E0%25B8%25A2%25E0%25B8%25AA%25E0%25B8%25B8%25E0%25B9%2580%25E0%25B8%2597%25E0%25B8%259E%25E0%25B8%25A3%25E0%25B8%25B2%25E0%25B8%258A%25E0%25B8%25A7%25E0%25B8%25A3%25E0%25B8%25A7%25E0%25B8%25B4%25E0%25B8%25AB%25E0%25B8%25B2%25E0%25B8%25A3', 0.99, '2026-10-01 16:22:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-10-01 16:22:00', 'verified', 'Tourism Authority of Thailand lists the temple open daily 5:00 AM-9:00 PM and tram service at THB 20. TAT identifies it as one of Chiang Mai’s key landmarks. Exact foreign admission fee was not clearly published on the fetched TAT page, so only tram price is treated as authoritative here.', '2026-10-01'),
('200042', '2003', 'Wat Phra Singh Woramahawihan', 'Wat Phra Singh', 'Major Lanna temple in the Old City, known for the Phra Buddha Sihing image, Lai Kham chapel and historic murals.', '1-2 hours', 'Morning', 'Combine with the Sunday Walking Street route and nearby Old City museums.', '', 'Chiang Mai', 0, 0, '', '', 'Temple grounds generally free; some inner buildings may charge foreign visitors, confirm onsite', 4.9, 4.8, 18.7886, 98.9813, 'Sam Lan Road, Phra Sing, Mueang Chiang Mai, Chiang Mai 50200', 'https://thai.tourismthailand.org/Attraction/%E0%B8%A7%E0%B8%B1%E0%B8%94%E0%B8%9E%E0%B8%A3%E0%B8%B0%E0%B8%AA%E0%B8%B4%E0%B8%87%E0%B8%AB%E0%B9%8C%E0%B8%A7%E0%B8%A3%E0%B8%A1%E0%B8%AB%E0%B8%B2%E0%B8%A7%E0%B8%B4%E0%B8%AB%E0%B8%B2%E0%B8%A3', 0.96, '2026-10-01 16:22:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-10-01 16:22:00', 'verified', 'TAT lists Wat Phra Singh open daily 6:00 AM-6:00 PM and describes its long history and major Lanna art/architecture. No reliable current fee was exposed on the fetched official page.', '2026-10-01'),
('200043', '2003', 'Wat Chedi Luang', 'Wat Chedi Luang', 'Historic Old City temple dominated by the massive ruined Lanna chedi that once housed the Emerald Buddha.', '1-2 hours', 'Late Afternoon', 'Visit before dusk when the brick chedi catches warm light; dress respectfully.', '', 'Chiang Mai', 0, 0, '', '', 'Foreign visitor fee commonly reported around THB 50; confirm onsite', 4.9, 4.8, 18.7871, 98.9864, '103 Prapokklao Road, Phra Sing, Mueang Chiang Mai, Chiang Mai 50200', NULL, 0.95, '2026-10-01 16:22:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-10-01 16:22:00', 'partial', 'TAT repeatedly includes Wat Chedi Luang among Chiang Mai’s key Old City temples. Current visitor sources commonly report roughly 5:00 AM-10:00 PM and a foreign visitor fee near THB 50, but no authoritative temple timetable/fee page was captured in this pass.', '2026-10-01'),
('200044', '2003', 'Wat Umong Suan Phutthatham', 'Wat Umong', 'Forest temple west of the city known for meditation grounds and ancient brick tunnels beneath a chedi.', '1-2 hours', 'Late Afternoon', 'Keep voices low around meditation areas; twilight gives the tunnel complex a distinctive atmosphere.', '', 'Chiang Mai', 0, 0, '', '', 'Free / donation-supported', 4.6, 4.7, 18.7833, 98.9525, '135 Moo 10, Suthep, Mueang Chiang Mai, Chiang Mai 50200', NULL, 0.88, '2026-10-01 16:22:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-10-01 16:22:00', 'partial', 'TAT describes Wat Umong as a roughly 700-year-old Buddhist temple with a tunnel system and recommends it in Chiang Mai itineraries. It is an active forest temple without a clearly published authoritative visitor timetable; practical daylight/evening hours are retained as partial.', '2026-10-01'),
('200045', '2003', 'Wat Suan Dok', 'Wat Suan Dok', 'Royal monastery west of the Old City, noted for its large open-air viharn and cluster of white royal-family chedis.', '1-1.5 hours', 'Morning', 'The white chedis are especially photogenic in soft morning light; monk-chat programs may operate separately.', '', 'Chiang Mai', 0, 0, '', '', 'Free / donation-supported', 4.5, 4.5, 18.7883, 98.9674, '139 Suthep Road, Suthep, Mueang Chiang Mai, Chiang Mai 50200', NULL, 0.82, '2026-10-01 16:22:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-10-01 16:22:00', 'partial', 'Wat Suan Dok is a well-established active Chiang Mai royal monastery. Current public listings generally show early-morning to evening access, but no sufficiently authoritative per-day visitor timetable or ticket page was captured in this pass.', '2026-10-01'),
('200046', '2003', 'Tha Phae Gate', 'Tha Phae Gate', 'Reconstructed eastern gate of Chiang Mai’s Old City and one of the city’s most recognizable public landmarks.', '30-60 minutes', 'Early Morning', 'Visit early or late afternoon for softer light and fewer crowds; Sunday Walking Street starts nearby.', '', 'Chiang Mai', 1, 1, '6:15 AM', '6:10 PM', 'Free public landmark', 4.8, 4.6, 18.7877, 99.0001, 'Tha Phae Road, Chang Khlan/Si Phum edge, Mueang Chiang Mai, Chiang Mai', NULL, 0.91, '2026-10-01 16:22:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-10-01 16:22:00', 'verified', 'A 2026 TAT destination e-book identifies Tha Phae Gate as a public space open daily 24 hours. TAT also describes it as the eastern entrance landmark of the historic walled city.', '2026-10-01'),
('200047', '2003', 'Tha Phae Sunday Walking Street', 'Sunday Walking Street', 'Weekly Sunday pedestrian market from Tha Phae Gate along Ratchadamnoen Road with handicrafts, local food, art and performances.', '2-4 hours', 'Evening', 'Arrive near 5 PM before peak density; the route runs toward Wat Phra Singh.', '', 'Chiang Mai', 0, 0, '', '', 'Free entry; vendor purchases extra', 4.9, 4.7, 18.7884, 98.9937, 'Ratchadamnoen Road, Mueang Chiang Mai, Chiang Mai', 'https://thai.tourismthailand.org/Shop/%E0%B8%96%E0%B8%99%E0%B8%99%E0%B8%84%E0%B8%99%E0%B9%80%E0%B8%94%E0%B8%B4%E0%B8%99%E0%B8%9B%E0%B8%A3%E0%B8%B0%E0%B8%95%E0%B8%B9%E0%B8%97%E0%B9%88%E0%B8%B2%E0%B9%81%E0%B8%9E', 0.95, '2026-10-01 16:22:00', NULL, 'attraction', 'Street Food', 'budget', 'veg-options', 'own', '2026-10-01 16:22:00', 'verified', 'TAT states the Tha Phae walking street operates only on Sundays, approximately 5:00 PM-10:00 PM, from Tha Phae Gate along Ratchadamnoen Road toward Wat Phra Singh.', '2026-10-01'),
('200048', '2003', 'Chiang Mai City Arts & Cultural Centre', 'Chiang Mai Cultural Centre', 'Municipal museum explaining Chiang Mai’s founding, urban history, people and cultural identity through multimedia exhibits.', '1.5-2 hours', 'Morning', 'Pair it with the Three Kings Monument and Lanna Folklife Museum across the same Old City cluster.', '', 'Chiang Mai', 0, 0, '', '', 'Adult THB 90; child THB 40 on current English museum site', 4.6, 4.5, 18.7905, 98.9868, 'Prapokklao Road, Si Phum, Mueang Chiang Mai, Chiang Mai 50200', 'https://cmocity.com/chiang-mai-art-cultural-centre/', 0.84, '2026-10-01 16:22:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-10-01 16:22:00', 'verified', 'Chiang Mai City Heritage Centre official site lists opening Wednesday-Sunday 8:30 AM-4:30 PM, closed Monday-Tuesday. Current English page lists admission THB 90 adult / THB 40 child.', '2026-10-01'),
('200049', '2003', 'Lanna Folklife Museum', 'Lanna Folklife Centre', 'Old City museum focused on Lanna ways of life, beliefs, ritual objects, crafts and Buddhist art.', '1-1.5 hours', 'Morning', 'Combine with the City Arts & Cultural Centre and Three Kings Monument; all are within a short walk.', '', 'Chiang Mai', 0, 0, '', '', 'Municipal museum admission; verify current individual/combined ticket onsite', 4.5, 4.5, 18.7908, 98.9874, 'Prapokklao Road, Si Phum, Mueang Chiang Mai, Chiang Mai 50200', 'https://cmocity.com/', 0.82, '2026-10-01 16:22:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-10-01 16:22:00', 'verified', 'Official Chiang Mai City Heritage Centre network lists Lanna Folklife Centre and states the municipal museums open Wednesday-Sunday 8:30 AM-4:30 PM and close Monday-Tuesday. Ticket presentation varies across site locales, so exact fee is left for refresh.', '2026-10-01'),
('200050', '2003', 'Chiang Mai National Museum', 'Chiang Mai National Museum', 'Fine Arts Department museum covering northern Thai archaeology, Lanna art, religion and the historical development of Chiang Mai.', '1.5-2 hours', 'Morning', 'Good context before temple-hopping if you want to understand Lanna art and chronology.', '', 'Chiang Mai', 0, 0, '', '', 'Paid admission; verify current foreign/Thai rate at museum', 4.4, 4.4, 18.8133, 98.9893, 'Chiang Mai-Lampang Superhighway, Chang Phueak, Mueang Chiang Mai, Chiang Mai', 'https://www.finearts.go.th/chiangmaimuseum', 0.8, '2026-10-01 16:22:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-10-01 16:22:00', 'verified', 'Fine Arts Department official museum site lists exhibition galleries open Wednesday-Sunday 9:00 AM-4:00 PM, closed Monday-Tuesday. Current fee was not clearly exposed on the pages captured in this pass.', '2026-10-01'),
('200051', '2003', 'Doi Inthanon National Park', 'Doi Inthanon', 'Mountain national park containing Thailand’s highest summit, cloud forest, waterfalls, viewpoints and highland trails.', 'Full day', 'Early Morning', 'Start before dawn if chasing sunrise; temperatures near the summit can be cold even when Chiang Mai city is warm.', '', 'Chiang Mai', 1, 1, '6:15 AM', '6:10 PM', 'Foreign adult THB 300; foreign child THB 150; vehicle fees extra', 5.0, 4.9, 18.5883, 98.4867, 'Ban Luang, Chom Thong, Chiang Mai 50160', 'https://www.dnp.go.th/', 0.99, '2026-10-01 16:22:00', NULL, 'attraction', NULL, 'mid', 'na', 'own', '2026-10-01 16:22:00', 'partial', 'DNP’s national park fee schedule places Doi Inthanon in the THB 300 foreign-adult / THB 150 foreign-child group. TAT highlights Doi Inthanon as a top Chiang Mai destination. Park gates and individual trails/sites can have differing seasonal hours, so the overall daily access window is marked partial.', '2026-10-01'),
('200052', '2003', 'Queen Sirikit Botanic Garden', 'Queen Sirikit Botanical Garden', 'Large mountain botanical garden in Mae Rim with glasshouses, forest trails and extensive tropical and highland plant collections.', '3-4 hours', 'Morning', 'Allow time for both the glasshouse complex and outdoor trails; distances inside the garden are substantial.', '', 'Chiang Mai', 0, 0, '', '', 'TAT lists THB 50 adult; children under 12 free', 4.7, 4.7, 18.8968, 98.8592, '100 Moo 9, Mae Raem, Mae Rim, Chiang Mai 50180', 'https://www.qsbg.org/', 0.9, '2026-10-01 16:22:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-10-01 16:22:00', 'verified', 'TAT official attraction page lists the garden open daily 8:30 AM-5:00 PM and admission THB 50 adults, free for children under 12. TAT describes it as Thailand’s first botanical garden.', '2026-10-01'),
('200053', '2003', 'Royal Park Rajapruek', 'Royal Park Rajapruek', 'Expansive horticultural park with Thai and international gardens, Ho Kham Royal Pavilion, tropical greenhouse and landscaped collections.', '3-4 hours', 'Morning', 'Use the included garden shuttle if you do not want to walk the full park in the heat.', '', 'Chiang Mai', 0, 0, '', '', 'Foreign adult THB 200; foreign child 100-140 cm THB 150; under 100 cm free', 4.7, 4.6, 18.7490, 98.9241, '334 Moo 3, Mae Hia, Mueang Chiang Mai, Chiang Mai 50100', 'https://www.royalparkrajapruek.org/', 0.89, '2026-10-01 16:22:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-10-01 16:22:00', 'verified', 'Official Royal Park Rajapruek site currently lists daily opening 8:00 AM-6:00 PM. Current foreign admission is THB 200 adult / THB 150 child 100-140 cm; children under 100 cm free. Electric garden shuttle is included.', '2026-10-01'),
('200054', '2003', 'Chiang Mai Night Safari', 'Chiang Mai Night Safari', 'Wildlife park with walking zones, tram safaris and evening animal-viewing programs near Doi Suthep-Pui foothills.', '3-5 hours', 'Evening', 'Arrive before dusk so you can walk the daytime trail before the night tram programs.', 'Online ticket recommended on busy dates', 'Chiang Mai', 0, 0, '', '', 'Foreign adult THB 800; foreign child THB 400 per TAT listing; online discounts may apply', 4.6, 4.5, 18.7431, 98.9177, '33 Moo 12, Nong Khwai, Hang Dong, Chiang Mai 50230', 'https://chiangmainightsafari.com/en/visit/', 0.87, '2026-10-01 16:22:00', NULL, 'attraction', NULL, 'premium', 'na', 'own', '2026-10-01 16:22:00', 'verified', 'Official Chiang Mai Night Safari schedule updated June 2026 lists opening 11:00 AM-10:00 PM, ticket office closing 9:00 PM. TAT currently lists foreign admission at THB 800 adult / THB 400 child; online ticket promotions can differ.', '2026-10-01'),
('200055', '2003', 'Elephant Nature Park', 'Elephant Nature Park', 'Rescue-focused elephant sanctuary project offering observation-centered day and half-day programs with rescued elephants and other animals.', 'Half or full day', 'Morning', 'Book at least a day ahead; programs include transfers and operate on fixed pickup schedules.', 'Advance booking required', 'Chiang Mai', 0, 0, '', '', 'Half-day program THB 2,500 adult / THB 1,250 child 3-11; other programs vary', 4.9, 4.9, 19.2154, 98.8604, 'Mae Taeng District, Chiang Mai; booking office: 1 Ratmakka Road, Phra Sing, Chiang Mai 50200', 'https://elephantnaturepark.org/book-now/', 0.96, '2026-10-01 16:22:00', NULL, 'attraction', NULL, 'premium', 'na', 'own', '2026-10-01 16:22:00', 'verified', 'Official Elephant Nature Park booking pages list multiple sanctuary programs. Current half-day visit price is THB 2,500 adult / THB 1,250 child 3-11; bookings generally close 24 hours before visit. Office hours are 7:00 AM-5:00 PM daily, while actual sanctuary schedules depend on the booked program.', '2026-10-01'),
('200056', '2003', 'Warorot Market', 'Kad Luang / Warorot Market', 'Large local market near the Ping River for northern sausages, chili dips, dried fruit, clothes and everyday Chiang Mai shopping.', '1.5-2 hours', 'Morning', 'Go in the morning for the fullest food selection and combine with nearby Ton Lam Yai flower market.', '', 'Chiang Mai', 0, 0, '', '', 'Free entry; vendor purchases extra', 4.7, 4.6, 18.7904, 99.0009, 'Chang Moi, Mueang Chiang Mai, Chiang Mai 50300', 'https://www.tourismthailand.org/Attraction/warorot-market', 0.88, '2026-10-01 16:22:00', NULL, 'attraction', 'Street Food', 'budget', 'veg-options', 'own', '2026-10-01 16:22:00', 'partial', 'TAT confirms Warorot Market (Kad Luang) as a major local market for northern foods and goods. The fetched official page does not expose a dependable daily timetable; current market listings generally show early-morning through evening operation, so hours remain partial.', '2026-10-01'),
('200057', '2003', 'Baan Kang Wat', 'Baan Kang Wat Artist Village', 'Small artist village and craft complex with studios, ceramics, illustration, cafés and independent creative shops.', '1.5-2 hours', 'Afternoon', 'Go on a non-rushed afternoon; some individual studios keep their own schedules.', '', 'Chiang Mai', 0, 0, '', '', 'Free entry; workshops and purchases extra', 4.6, 4.6, 18.7769, 98.9518, '191-197 Soi Wat Umong, Suthep, Mueang Chiang Mai, Chiang Mai 50200', NULL, 0.83, '2026-10-01 16:22:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-10-01 16:22:00', 'partial', 'TAT recommends Baan Kang Wat as an art complex where local artists display crafts and artwork. Current venue listings generally show Tuesday-Sunday daytime operation and Monday closure, but no authoritative venue timetable was captured in this pass.', '2026-10-01'),
('200058', '2003', 'Wat Phra That Doi Kham', 'Wat Doi Kham', 'Hilltop temple southwest of Chiang Mai with a large seated Buddha and broad views toward the city and Royal Park Rajapruek.', '1-2 hours', 'Morning', 'Combine with Royal Park Rajapruek; mornings are cooler and usually clearer for city views.', '', 'Chiang Mai', 1, 1, '6:15 AM', '6:10 PM', 'Free / donation-supported', 4.6, 4.6, 18.7597, 98.9184, '108 Moo 3, Mae Hia, Mueang Chiang Mai, Chiang Mai 50200', 'https://thai.tourismthailand.org/Attraction/%E0%B8%A7%E0%B8%B1%E0%B8%94%E0%B8%9E%E0%B8%A3%E0%B8%B0%E0%B8%98%E0%B8%B2%E0%B8%95%E0%B8%B8%E0%B8%94%E0%B8%AD%E0%B8%A2%E0%B8%84%E0%B8%B3', 0.85, '2026-10-01 16:22:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-10-01 16:22:00', 'verified', 'TAT lists Wat Phra That Doi Kham open daily 7:30 AM-6:00 PM and describes it as an ancient temple in Mae Hia with more than 1,300 years of history.', '2026-10-01'),
('200059', '2003', 'Khao Soi Mae Sai', 'Khao Soi Mae Sai', 'Local noodle shop specializing in Chiang Mai khao soi with rich curry broth, crisp noodles and a choice of meat toppings.', '45-60 minutes', 'Lunch', 'Go before the lunch peak because the shop closes in the afternoon and is closed Sunday.', '', 'Chiang Mai', 0, 0, '', '', 'Budget; MICHELIN price category ฿', 4.7, 4.7, 18.8051, 98.9798, '29/1 Ratchaphruek Road, Chang Phueak, Mueang Chiang Mai, Chiang Mai 50300', NULL, 0.88, '2026-10-01 16:22:00', NULL, 'restaurant', 'Khao Soi / Noodles', 'budget', 'veg-options', 'own', '2026-10-01 16:22:00', 'verified', 'MICHELIN Guide currently lists Khao Soi Mae Sai at 29/1 Ratchaphruek Road, open Monday-Saturday 8:00 AM-4:00 PM and closed Sunday, price category ฿.', '2026-10-01'),
('200060', '2003', 'Huen Muan Jai', 'Huen Muan Jai', 'Lanna-style garden restaurant serving a broad range of Northern Thai dishes in wooden pavilions and indoor rooms.', '1-2 hours', 'Evening', 'Dinner can be busy; Wednesday is the regular closure day.', 'Reservation recommended for groups', 'Chiang Mai', 0, 0, '', '', 'Mid-range; MICHELIN price category ฿฿', 4.7, 4.7, 18.8050, 98.9792, '24 Ratchaphruek Road, Chang Phueak, Mueang Chiang Mai, Chiang Mai 50300', NULL, 0.87, '2026-10-01 16:22:00', NULL, 'restaurant', 'Northern Thai', 'mid', 'veg-options', 'own', '2026-10-01 16:22:00', 'verified', 'MICHELIN Guide currently lists Huen Muan Jai at 24 Ratchaphruek Road, Northern Thai cuisine, price category ฿฿, closed Wednesday. Current MICHELIN locale pages show service around 11:00 AM-9:00 PM; one locale exposes a lunch/dinner split, so last-order/break details should be checked when publishing.', '2026-10-01');
