INSERT INTO festivals (id, state_id, city_id, place_id, festival_name, timing_label, lunar_note, duration_label, description, source, updated_at) VALUES
(300007, 9003, 2003, NULL, 'Yi Peng & Loy Krathong in Chiang Mai', 'November', 'Full moon of the 12th Thai lunar month; exact dates shift yearly', '2-3 days', 'Chiang Mai’s major lantern and krathong celebrations include temple ceremonies, illuminated streets, processions and river activities. Exact sanctioned lantern zones and event dates must be refreshed yearly.', 'own', '2026-10-01 16:22:00'),
(300008, 9003, 2003, 200046, 'Songkran in Chiang Mai', '13-15 April', 'Thai solar New Year; civic events can extend beyond the core holiday', '3+ days', 'Chiang Mai hosts large Songkran celebrations around the Old City moat, Tha Phae Gate and temples, combining water festivities with merit-making and cultural programming.', 'own', '2026-10-01 16:22:00'),
(300009, 9003, 2003, NULL, 'Chiang Mai Flower Festival', 'Early February', 'Annual civic event; exact dates vary by year', '3 days', 'Annual flower festival featuring floral floats, garden displays and parades in Chiang Mai; refresh the exact year-specific route and dates before publishing.', 'own', '2026-10-01 16:22:00');
INSERT INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score, created_at, google_place_id, category, cuisine, price_band, veg_flag, source, updated_at, verification_status, verification_notes, verified_at) VALUES
('200061', '2004', 'Sanctuary of Truth Museum', 'Sanctuary of Truth', 'Monumental hand-carved wooden museum-temple on the sea in North Pattaya, combining Thai, Khmer, Indian and Chinese philosophical motifs.', '2-3 hours', 'Morning', 'Join a guided tour to understand the carvings; modest dress is required.', 'Advance booking recommended in peak periods', 'Chon Buri', 0, 1, '', '6:00 PM', 'Day tour adult THB 500; child 110-140 cm THB 250; night tour adult THB 700', 5.0, 4.9, 12.9727, 100.8892, '206/2 Moo 5, Pattaya-Naklua Road, Bang Lamung, Chonburi 20150', 'https://sanctuaryoftruthmuseum.com/visit-us/', 0.99, '2026-10-01 16:22:00', NULL, 'attraction', NULL, 'mid', 'na', 'own', '2026-10-01 16:22:00', 'verified', 'Official Sanctuary of Truth Museum page checked 2026-10-01: day ticket sales 8:00 AM-5:00 PM, day tours 8:20 AM-6:00 PM, night ticket sales 5:30-7:30 PM, night tours 6:20-8:30 PM. Adult day THB 500 / night THB 700; children 110-140 cm THB 250 / 350; under 110 cm free.', '2026-10-01'),
('200062', '2004', 'Nong Nooch Tropical Garden Pattaya', 'Nong Nooch Tropical Garden', 'Large botanical and landscaped garden complex south of Pattaya with themed gardens, cultural shows and extensive plant collections.', '4-6 hours', 'Morning', 'Start early because the grounds are large; show schedules should be checked on arrival.', 'Online booking recommended on weekends', 'Chon Buri', 0, 0, '', '', 'Ticket packages vary; children under 140 cm free when accompanied by family per current promotion', 4.9, 4.8, 12.7666, 100.9328, '34/1 Moo 7, Na Chom Thian, Sattahip, Chonburi 20250', 'https://www.nongnoochpattaya.com/en/', 0.97, '2026-10-01 16:22:00', NULL, 'attraction', NULL, 'mid', 'na', 'own', '2026-10-01 16:22:00', 'verified', 'Official Nong Nooch site states daily opening 8:00 AM-6:00 PM. 2026 official promotions state children under 140 cm enter free with family and shows operate multiple times daily; package pricing changes frequently, so no single base rate is frozen here.', '2026-10-01'),
('200063', '2004', 'Khao Chi Chan Buddha Mountain', 'Buddha Mountain', 'Giant Buddha image laser-etched into a limestone cliff south of Pattaya, set within landscaped grounds.', '45-60 minutes', 'Morning', 'Combine with Wat Yansangwararam and Nong Nooch; dress respectfully.', '', 'Chon Buri', 0, 0, '', '', 'Free entry', 4.7, 4.6, 12.7585, 100.9566, 'Na Chom Thian, Sattahip, Chonburi', 'https://www.tourismthailand.org/Destinations/Provinces/Pattaya/469', 0.88, '2026-10-01 16:22:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-10-01 16:22:00', 'verified', 'Tourism Authority of Thailand Pattaya destination page explicitly lists Khao Chee Chan Buddha Mountain open 6:00 AM-6:00 PM and advises modest dress. Public outdoor attraction with no admission fee commonly charged.', '2026-10-01'),
('200064', '2004', 'Wat Yansangwararam Woramahawihan', 'Wat Yansangwararam', 'Royal Buddhist temple complex south of Pattaya with Thai religious architecture, landscaped grounds and nearby cultural sites.', '1.5-2 hours', 'Morning', 'Pair with Khao Chi Chan; temple buildings may have more limited access than the surrounding grounds.', '', 'Chon Buri', 0, 0, '', '', 'Free / donation-supported', 4.6, 4.6, 12.7890, 100.9570, 'Huai Yai, Bang Lamung, Chonburi 20250', NULL, 0.84, '2026-10-01 16:22:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-10-01 16:22:00', 'partial', 'Wat Yansangwararam is a major royal temple complex commonly paired with Khao Chi Chan in Pattaya-area itineraries. Current public sources generally show daytime access, but a sufficiently authoritative per-day visitor schedule was not captured in this pass.', '2026-10-01'),
('200065', '2004', 'Pattaya Beach', 'Pattaya Beach', 'Central Pattaya’s approximately three-kilometre urban beach, lined with hotels, restaurants, shopping and marine-activity operators.', '2-4 hours', 'Late Afternoon', 'The northern section is generally quieter; use licensed operators for marine activities and follow local safety flags.', '', 'Chon Buri', 1, 1, '6:10 AM', '6:05 PM', 'Free public beach; water activities extra', 4.8, 4.3, 12.9369, 100.8833, 'Pattaya Beach Road, Nong Prue, Bang Lamung, Chonburi 20150', 'https://thai.tourismthailand.org/Attraction/%E0%B8%AB%E0%B8%B2%E0%B8%94%E0%B8%9E%E0%B8%B1%E0%B8%97%E0%B8%A2%E0%B8%B2', 0.9, '2026-10-01 16:22:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-10-01 16:22:00', 'verified', 'TAT official Pattaya Beach page describes it as the city’s best-known beach, about 3 km long, with water sports and a quieter northern section. It is a public beach without a formal visitor gate.', '2026-10-01'),
('200066', '2004', 'Jomtien Beach', 'Jomtien Beach', 'Long beach south of central Pattaya with a more relaxed atmosphere, beach chairs, seafood and water sports.', '3-5 hours', 'Morning', 'Choose a section away from active sand-nourishment work and check sea conditions before swimming.', '', 'Chon Buri', 1, 1, '6:10 AM', '6:05 PM', 'Free public beach; rentals and water sports extra', 4.8, 4.6, 12.8910, 100.8746, 'Jomtien Beach Road, Pattaya, Chonburi', NULL, 0.91, '2026-10-01 16:22:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-10-01 16:22:00', 'verified', 'TAT’s Pattaya itinerary describes Jomtien as a quieter resort beach about 3 km south of Pattaya Beach. 2026 local verification notes ongoing sand-nourishment works on parts of the beach; public access itself is open and unticketed.', '2026-10-01'),
('200067', '2004', 'Ko Lan', 'Koh Larn', 'Popular island day trip off Pattaya with multiple beaches, viewpoints, local transport and water activities.', 'Full day', 'Morning', 'Take an early ferry or speedboat and choose one or two beaches rather than trying to cover the entire island.', '', 'Chon Buri', 1, 1, '6:10 AM', '6:05 PM', 'Island entry free; ferry/speedboat and local transport extra', 5.0, 4.8, 12.9190, 100.7790, 'Ko Lan, Bang Lamung, Chonburi', 'https://www.tourismthailand.org/Destinations/Provinces/Pattaya/469', 0.98, '2026-10-01 16:22:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-10-01 16:22:00', 'verified', 'TAT Pattaya destination page identifies Ko Lan as a primary Pattaya highlight and a practical one-day trip, with minibuses and motorbike taxis available on the island. Ferry timetables change by pier/operator and are intentionally not hard-coded here.', '2026-10-01'),
('200068', '2004', 'Underwater World Pattaya', 'Underwater World Pattaya', 'Indoor aquarium with coral, marine life and a 105-metre acrylic tunnel plus scheduled feeding programs.', '1.5-2 hours', 'Afternoon', 'Good rainy-day option; arrive before the last-admission cutoff.', '', 'Chon Buri', 0, 0, '', '', 'Adult THB 550; child 91-130 cm THB 320', 4.5, 4.4, 12.8958, 100.8977, '22/22 Moo 11, Sukhumvit Road, Nong Prue, Bang Lamung, Chonburi 20150', 'https://underwaterworldpattaya.com/', 0.82, '2026-10-01 16:22:00', NULL, 'attraction', NULL, 'mid', 'na', 'own', '2026-10-01 16:22:00', 'verified', 'Official Underwater World Pattaya site checked 2026-10-01: open daily 9:00 AM-6:00 PM, last admission 5:30 PM. Adult THB 550; child 91-130 cm THB 320.', '2026-10-01'),
('200069', '2004', 'Ramayana Water Park', 'Ramayana Water Park', 'Large water park near Na Chom Thian with slides, pools, family zones and landscaped grounds.', 'Full day', 'Morning', 'Buy online because online-ticket holders are prioritized if the park reaches capacity.', 'Online booking recommended', 'Chon Buri', 0, 0, '', '', 'Ticket prices vary by promotion/package; official website offers online discounts', 4.8, 4.7, 12.7496, 100.9624, '9 Moo 7, Ban Yen Road, Na Chom Thian, Sattahip, Chonburi 20250', 'https://www.ramayanawaterpark.com/', 0.92, '2026-10-01 16:22:00', NULL, 'attraction', NULL, 'premium', 'na', 'own', '2026-10-01 16:22:00', 'verified', 'Official Ramayana Water Park site checked 2026-10-01: open 11:00 AM-6:00 PM, closed Wednesdays. Official FAQ recommends online purchase and notes capacity priority for online ticket holders. Prices are promotion-dependent.', '2026-10-01'),
('200070', '2004', 'Columbia Pictures Aquaverse', 'Columbia Pictures Aquaverse', 'Movie-themed water and entertainment park featuring zones inspired by Columbia and Sony film properties.', 'Full day', 'Morning', 'Check ride restrictions before buying; online rates can be significantly lower than gate/list prices.', 'Online booking recommended', 'Chon Buri', 0, 0, '', '', 'Current online Single Ticket THB 990 adult; Essential Pass adult THB 1,380; child Essential Pass THB 890', 4.7, 4.6, 12.7690, 100.9132, '888 Moo 8, Na Chom Thian, Sattahip, Chonburi 20250', 'https://columbiapicturesaquaverse.com/en/', 0.9, '2026-10-01 16:22:00', NULL, 'attraction', NULL, 'premium', 'na', 'own', '2026-10-01 16:22:00', 'verified', 'Official Aquaverse site checked 2026-10-01: open 10:00 AM-6:00 PM, closed Wednesdays. Current displayed online tickets include THB 990 adult park-access-only, THB 1,380 adult Essential Pass and THB 890 child Essential Pass; promotional rates may change.', '2026-10-01'),
('200071', '2004', 'Terminal 21 Pattaya', 'Terminal 21 Pattaya', 'Airport-themed shopping mall with destination-themed floors, dining, supermarket, cinema and indoor photo spots.', '2-4 hours', 'Afternoon', 'Use it as a heat/rain break and for inexpensive food-court meals.', '', 'Chon Buri', 0, 0, '', '', 'Free entry; shopping/dining extra', 4.6, 4.5, 12.9497, 100.8892, '777, 777/1 Moo 6, Na Kluea, Bang Lamung, Chonburi 20150', 'https://www.terminal21.co.th/pattaya/en/home-en/', 0.84, '2026-10-01 16:22:00', NULL, 'attraction', NULL, 'budget', 'veg-options', 'own', '2026-10-01 16:22:00', 'verified', 'Official Terminal 21 Pattaya site checked 2026-10-01: open Monday-Sunday 11:00 AM-10:00 PM.', '2026-10-01'),
('200072', '2004', 'Ripley’s Believe It or Not! Pattaya', 'Ripley’s Pattaya', 'Indoor entertainment complex at Royal Garden Plaza with the Odditorium plus mazes, horror attractions, waxworks and simulator experiences.', '2-4 hours', 'Afternoon', 'Choose attractions before buying a bundle; prices vary substantially by combination.', '', 'Chon Buri', 0, 0, '', '', 'Single attractions and bundles vary; official site advertises multi-attraction discounts', 4.5, 4.4, 12.9294, 100.8780, '218 Moo 10, Beach Road, Nong Prue, Bang Lamung, Chonburi 20150', 'https://ripleysthailand.com/', 0.81, '2026-10-01 16:22:00', NULL, 'attraction', NULL, 'mid', 'na', 'own', '2026-10-01 16:22:00', 'verified', 'Official Ripley Thailand site checked 2026-10-01: Pattaya Beach Road complex open daily 11:00 AM-10:00 PM and currently comprises 10 attractions. Ticket combinations/promotions change, so no single package price is frozen.', '2026-10-01'),
('200073', '2004', 'Pattaya Floating Market', 'Four Regions Floating Market', 'Large market attraction themed around Thailand’s four regions, with wooden walkways, food, crafts and cultural demonstrations.', '2-3 hours', 'Late Morning', 'Go early before tour-group peaks; some activities and boat rides cost extra.', '', 'Chon Buri', 0, 0, '', '', 'Paid attraction; package prices vary by channel and activity', 4.5, 4.2, 12.8679, 100.9058, '451/304 Moo 12, Sukhumvit Road, Nong Prue, Bang Lamung, Chonburi 20150', NULL, 0.79, '2026-10-01 16:22:00', NULL, 'attraction', 'Street Food', 'mid', 'veg-options', 'own', '2026-10-01 16:22:00', 'partial', 'TAT includes Pattaya Floating Market in its current Chon Buri-Pattaya itinerary. Current listings generally show daytime operation, but a reliable current official hours/fee page was not captured in this pass; keep ticket package data dynamic.', '2026-10-01'),
('200074', '2004', 'Art in Paradise Pattaya', 'Art in Paradise', 'Interactive 3D illusion-art museum designed for visitors to pose inside large perspective paintings and themed scenes.', '1.5-2 hours', 'Afternoon', 'Best with a phone/camera and a small group so someone can frame the illusion shots.', '', 'Chon Buri', 0, 0, '', '', 'TAT Japan currently lists adult THB 300 / child THB 200; some 2026 local listings show adult THB 400', 4.4, 4.4, 12.9504, 100.8873, '78/34 Moo 9, Pattaya Sai 2, Nong Prue, Bang Lamung, Chonburi 20150', NULL, 0.78, '2026-10-01 16:22:00', NULL, 'attraction', NULL, 'mid', 'na', 'own', '2026-10-01 16:22:00', 'partial', 'Tourism Authority of Thailand Japan lists Art in Paradise Pattaya open daily 9:00 AM-9:00 PM and adult/child fees THB 300/200. A separate 2026 locally verified listing shows adult THB 400, so current adult pricing is marked partial until box-office confirmation.', '2026-10-01'),
('200075', '2004', 'Mini Siam', 'Mini Siam & Mini World', 'Open-air miniature park recreating famous Thai and global landmarks at reduced scale.', '1.5-2 hours', 'Late Afternoon', 'Late afternoon is more comfortable and lets you stay into the illuminated evening period.', '', 'Chon Buri', 0, 0, '', '', 'Foreign adult THB 300; foreign child THB 150', 4.3, 4.3, 12.9568, 100.9042, '387 Moo 6, Sukhumvit Road, Na Kluea, Bang Lamung, Chonburi 20150', NULL, 0.76, '2026-10-01 16:22:00', NULL, 'attraction', NULL, 'mid', 'na', 'own', '2026-10-01 16:22:00', 'verified', 'TAT Japan lists Mini Siam 9:00 AM-7:00 PM daily with THB 300 admission. Thailand DASTA listing also confirms foreign adult THB 300 / child THB 150, though it displays a broader 7:00 AM-9:00 PM schedule; the more recent TAT schedule is used here.', '2026-10-01'),
('200076', '2004', 'Wat Phra Yai (Big Buddha Temple)', 'Pattaya Big Buddha', 'Hilltop Buddhist temple on Pratumnak Hill centered on a large golden seated Buddha overlooking Pattaya.', '1 hour', 'Morning', 'Dress respectfully and combine with Pattaya Viewpoint nearby.', '', 'Chon Buri', 1, 1, '6:10 AM', '6:05 PM', 'Free / donation-supported', 4.6, 4.5, 12.9168, 100.8686, 'Phra Tamnak Hill, Nong Prue, Bang Lamung, Chonburi', NULL, 0.82, '2026-10-01 16:22:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-10-01 16:22:00', 'partial', 'Wat Phra Yai is a major Pattaya hilltop temple and standard city attraction. Current visitor sources generally show early-morning through evening access, but no sufficiently authoritative per-day timetable was captured in this pass.', '2026-10-01'),
('200077', '2004', 'Pattaya City Viewpoint (Khao Phra Tamnak)', 'Pattaya Viewpoint', 'Public hilltop viewpoint on Pratumnak Hill overlooking Pattaya Bay and the curved city coastline.', '30-60 minutes', 'Sunset', 'Sunset is busiest; morning gives clearer photos and easier parking.', '', 'Chon Buri', 1, 1, '6:10 AM', '6:05 PM', 'Free public viewpoint', 4.7, 4.6, 12.9214, 100.8677, 'Khao Phra Tamnak, Nong Prue, Bang Lamung, Chonburi', NULL, 0.86, '2026-10-01 16:22:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-10-01 16:22:00', 'partial', 'Established public viewpoint overlooking Pattaya Bay. No authoritative gate timetable was found; practical access is generally daytime/evening and may be affected by events or traffic controls.', '2026-10-01'),
('200078', '2004', 'Tiffany’s Show Pattaya', 'Tiffany’s Show', 'Long-running stage production featuring elaborate costumes, choreography and transgender performers in a purpose-built Pattaya theatre.', '1.5 hours', 'Evening', 'Book ahead for preferred seating; photography during the performance is restricted.', 'Advance booking recommended', 'Chon Buri', 0, 0, '', '', 'Current official sales show Mezzanine THB 1,200; VIP tiers THB 2,200-2,800', 4.7, 4.6, 12.9492, 100.8877, '464 Moo 9, Pattaya Sai Song Road, Nong Prue, Bang Lamung, Chonburi 20150', 'https://www.tiffany-show.co.th/', 0.88, '2026-10-01 16:22:00', NULL, 'attraction', NULL, 'premium', 'na', 'own', '2026-10-01 16:22:00', 'verified', 'Tiffany official site is active. Current official LINE shop lists showtimes 6:00 PM, 7:30 PM and 9:00 PM, with Mezzanine THB 1,200 and VIP tiers THB 2,200-2,800. TAT also lists the same three nightly showtimes.', '2026-10-01'),
('200079', '2004', 'Moom Aroi Naklua', 'Moom Aroi Restaurant', 'Large seaside seafood restaurant in Naklua known for Thai seafood dishes and sunset-facing outdoor tables.', '1.5-2 hours', 'Evening', 'Reserve or arrive early for outdoor seating around sunset.', 'Reservation recommended for groups', 'Chon Buri', 0, 1, '', '6:05 PM', 'Mid-range seafood; à la carte pricing', 4.6, 4.5, 12.9750, 100.8955, 'Naklua Road area, Bang Lamung, Pattaya, Chonburi', NULL, 0.83, '2026-10-01 16:22:00', NULL, 'restaurant', 'Thai Seafood', 'mid', 'veg-options', 'own', '2026-10-01 16:22:00', 'verified', 'DASTA SMART destination listing identifies Moom Aroi Naklua as a famous seaside Pattaya seafood restaurant and lists daily opening 11:00 AM-11:00 PM.', '2026-10-01'),
('200080', '2004', 'The Glass House Silver', 'Glass House Silver', 'North Pattaya beachfront restaurant serving seafood, Thai dishes, Japanese options and European classics in indoor and seaside seating.', '1.5-2 hours', 'Evening', 'Reserve for sunset-facing outdoor tables.', 'Reservation recommended', 'Chon Buri', 0, 1, '', '6:05 PM', 'Mid to premium; à la carte pricing', 4.6, 4.6, 12.9640, 100.8849, '456 Zire Wongamat (687 Moo 5), Soi Naklua 18, Bang Lamung, Pattaya, Chonburi 20150', 'https://www.glasshouse-pattaya.com/en/', 0.84, '2026-10-01 16:22:00', NULL, 'restaurant', 'Seafood / Thai / International', 'premium', 'veg-options', 'own', '2026-10-01 16:22:00', 'verified', 'Official Glass House Pattaya website checked 2026-10-01: Glass House Silver at Zire Wongamat, Soi Naklua 18, open every day 11:00 AM-midnight.', '2026-10-01');
