INSERT INTO festivals (id, state_id, city_id, place_id, festival_name, timing_label, lunar_note, duration_label, description, source, updated_at) VALUES
(300010, 9004, 2004, 200065, 'Pattaya Music Festival 2026', '6-7, 13-14, 20-21, 27-28 March 2026', 'Fixed 2026 civic schedule; refresh yearly', 'Four weekends', '2026 festival stages were scheduled across Central Pattaya Beach, Jomtien Beach, Samae Beach on Ko Lan, and Lan Pho Naklua Park.', 'own', '2026-10-01 16:22:00'),
(300011, 9004, 2004, 200065, 'Pattaya Songkran Summer Festival 2026', '17-19 April 2026', 'Part of Chon Buri Wan Lai / Songkran traditions; dates vary yearly', '3 days', 'TAT listed the Pattaya Songkran Summer Festival 2026 at Central Pattaya Beach from 17-19 April, within Chon Buri’s extended Wan Lai celebrations.', 'own', '2026-10-01 16:22:00'),
(300012, 9004, 2004, NULL, 'Tomorrowland Thailand 2026', '11-13 December 2026', 'One-off confirmed 2026 edition; future recurrence must be reverified', '3 days', 'TAT announced Tomorrowland Thailand’s first full-scale Asian edition at Wisdom Valley Pattaya, Chon Buri, on 11-13 December 2026.', 'own', '2026-10-01 16:22:00');
INSERT INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score, created_at, google_place_id, category, cuisine, price_band, veg_flag, source, updated_at, verification_status, verification_notes, verified_at) VALUES
('200081','2005','Ao Nang Beach','Ao Nang Beach','Krabi’s main resort beach and long-tail boat hub, backed by restaurants, hotels and sunset-facing promenade activity.','2-4 hours','Late Afternoon','Use Ao Nang as a boat-launch base for Railay and the offshore islands; sunset is the busiest period.','','Krabi',0,1,'','6:05 PM','Free public beach; boat transfers and activities extra',4.9,4.6,8.0323,98.8226,'Ao Nang, Mueang Krabi, Krabi 81180',NULL,0.95,'2026-10-01 16:22:00',NULL,'attraction',NULL,'budget','na','own','2026-10-01 16:22:00','verified','Tourism Authority of Thailand identifies Ao Nang as Krabi’s primary seaside visitor hub, with hotels, restaurants, souvenir shops and access to nearby beaches/islands. Public beach access is unticketed.','2026-10-01'),
('200082','2005','Railay Beach','Railay Bay','Boat-access peninsula beach beneath dramatic limestone cliffs, internationally known for scenery, climbing and access to Phra Nang.','Half day','Morning','Take an early long-tail boat before the day-trip peak and walk between Railay West, Railay East and Phra Nang.','','Krabi',0,1,'','6:05 PM','Beach access free; boat transfer and national-park/island trips extra',5.0,4.9,8.0115,98.8373,'Railay, Ao Nang, Mueang Krabi, Krabi','https://www.tourismthailand.org/Trip-Planner/Suggestion-Detail/ao-railay-railay-bay-tham-phra-nang-beach-phra-nang-cave-beach-thale-waek-separated-sea-ko-po-da-khao-khanap-nam-viewpoint-tha-pom-khlang-cave',0.99,'2026-10-01 16:22:00',NULL,'attraction',NULL,'budget','na','own','2026-10-01 16:22:00','verified','TAT features Ao Railay as a core Krabi itinerary stop alongside Phra Nang, Thale Waek and Ko Poda. The peninsula is practically reached by boat and has no standalone beach admission.','2026-10-01'),
('200083','2005','Phra Nang Cave Beach','Phranang Cave Beach','Scenic limestone-cliff beach at the south end of Railay, famous for clear water and the Princess Cave shrine.','2-3 hours','Morning','Walk from Railay and arrive early; shade becomes limited as crowds build.','','Krabi',0,1,'','6:05 PM','Free beach access; boat transfer extra',5.0,4.9,8.0069,98.8371,'Railay Peninsula, Ao Nang, Mueang Krabi, Krabi','https://www.tourismthailand.org/Trip-Planner/Suggestion-Detail/ao-railay-railay-bay-tham-phra-nang-beach-phra-nang-cave-beach-thale-waek-separated-sea-ko-po-da-khao-khanap-nam-viewpoint-tha-pom-khlang-cave',0.98,'2026-10-01 16:22:00',NULL,'attraction',NULL,'budget','na','own','2026-10-01 16:22:00','verified','TAT includes Phranang Cave Beach in its official Krabi trip planner. It is an open beach reached through Railay; no separate fixed admission was identified.','2026-10-01'),
('200084','2005','Tonsai Beach','Ton Sai Beach','Small cliff-backed beach between Ao Nang and Railay associated with budget stays, climbing and a laid-back atmosphere.','2-3 hours','Morning','Access is tide-dependent on foot from Railay or by boat; carry suitable footwear.','','Krabi',0,1,'','6:05 PM','Free public beach; boat transfer extra',4.6,4.6,8.0186,98.8303,'Ao Nang, Mueang Krabi, Krabi',NULL,0.84,'2026-10-01 16:22:00',NULL,'attraction',NULL,'budget','na','own','2026-10-01 16:22:00','partial','Tonsai is an established Krabi climbing/beach area adjacent to Railay. No authoritative visitor timetable applies; access varies with tide and boat conditions.','2026-10-01'),
('200085','2005','Noppharat Thara Beach','Noppharat Thara Beach','Long, shaded beach north of Ao Nang and part of Hat Noppharat Thara–Mu Ko Phi Phi National Park.','2-4 hours','Late Afternoon','Low tide exposes a broad shoreline; combine with the night market area nearby.','','Krabi',0,1,'','6:05 PM','Beach access typically free; protected-area/island fees may apply to park excursions',4.7,4.6,8.0521,98.8112,'Noppharat Thara, Ao Nang, Mueang Krabi, Krabi','https://www.tourismthailand.org/Trip-Planner/Suggestion-Detail/krabi-trang-4-days',0.9,'2026-10-01 16:22:00',NULL,'attraction',NULL,'budget','na','own','2026-10-01 16:22:00','verified','TAT includes Noppharat Thara Beach in its official Krabi trip planner and identifies the area as part of the national-park coast.','2026-10-01'),
('200086','2005','Ko Poda','Poda Island','Compact limestone island off Ao Nang with white sand, clear water and popular snorkeling stops on four-island boat routes.','3-4 hours','Morning','Go on an early boat and bring reef-safe sun protection; conditions can change quickly in monsoon seas.','Boat tour or private long-tail recommended','Krabi',0,1,'','6:05 PM','Protected-area/national-park fee may apply; boat fare extra',4.9,4.8,7.9716,98.8084,'Ko Poda, Ao Nang, Mueang Krabi, Krabi','https://www.tourismthailand.org/Trip-Planner/Suggestion-Detail/krabi-trang-4-days',0.95,'2026-10-01 16:22:00',NULL,'attraction',NULL,'mid','na','own','2026-10-01 16:22:00','verified','TAT officially includes Ko Poda in Krabi island itineraries and describes the surrounding Poda/Chicken-island cluster as suitable for beach time and snorkeling.','2026-10-01'),
('200087','2005','Thale Waek','Separated Sea / Thale Waek','Low-tide sandbar phenomenon linking small islands in the Chicken–Tub–Mor island group off Krabi.','2-3 hours','Low Tide','Time the visit around tide charts; the sandbar can disappear completely at higher tide.','Boat tour required','Krabi',0,1,'','6:05 PM','National-park/protected-area fee and boat fare apply',4.9,4.8,7.9688,98.8106,'Ko Dam Khwan area, Mueang Krabi, Krabi','https://www.tourismthailand.org/Trip-Planner/Suggestion-Detail/krabi-trang-4-days',0.96,'2026-10-01 16:22:00',NULL,'attraction',NULL,'mid','na','own','2026-10-01 16:22:00','verified','TAT calls Thale Waek one of Thailand’s unseen highlights and explains that the white sandbar appears as the tide recedes, connecting islands in the Ko Dam Khwan group.','2026-10-01'),
('200088','2005','Ko Hong','Hong Island','Signature island within Than Bok Khorani National Park, known for its enclosed lagoon, pale sand and limestone cliffs.','Half day','Morning','Use a licensed boat from Ao Nang or Klong Muang and arrive before the main tour flotillas.','Boat tour required','Krabi',0,1,'','6:05 PM','Than Bok Khorani National Park foreign adult THB 300; child THB 100; boat extra',5.0,4.9,8.0798,98.6789,'Than Bok Khorani National Park, Krabi','https://thai.tourismthailand.org/Attraction/%E0%B8%AD%E0%B8%B8%E0%B8%97%E0%B8%A2%E0%B8%B2%E0%B8%99%E0%B9%81%E0%B8%AB%E0%B9%88%E0%B8%87%E0%B8%8A%E0%B8%B2%E0%B8%95%E0%B8%B4%E0%B8%98%E0%B8%B2%E0%B8%A3%E0%B9%82%E0%B8%9A%E0%B8%81%E0%B8%82%E0%B8%A3%E0%B8%93%E0%B8%B5',0.98,'2026-10-01 16:22:00',NULL,'attraction',NULL,'mid','na','own','2026-10-01 16:22:00','verified','TAT lists Ko Hong among the islands of Than Bok Khorani National Park. Current TAT park information states foreign admission THB 300 adult / THB 100 child.','2026-10-01'),
('200089','2005','Ko Phi Phi Don','Phi Phi Don','Main inhabited Phi Phi island with Tonsai village, beaches, viewpoints, lodging and boat connections.','Full day or overnight','Morning','If day-tripping, take an early ferry/speedboat; overnighting allows quieter morning and evening hours.','Ferry/speedboat booking recommended','Krabi',1,1,'6:15 AM','6:05 PM','Marine national-park fee may apply to protected areas; transport extra',5.0,4.8,7.7407,98.7784,'Ko Phi Phi Don, Ao Nang, Mueang Krabi, Krabi','https://www.tourismthailand.org/Destinations/Provinces/Krabi/344',0.99,'2026-10-01 16:22:00',NULL,'attraction',NULL,'mid','na','own','2026-10-01 16:22:00','verified','TAT identifies Koh Phi Phi as one of Krabi’s major island destinations and part of the province’s national-park/island tourism core.','2026-10-01'),
('200090','2005','Maya Bay','Maya Bay','World-famous limestone-enclosed bay on Phi Phi Leh with turquoise water and protected beach access.','1-2 hours','Morning','Swimming restrictions and seasonal closures are conservation measures; check current park status before travel.','Boat tour required','Krabi',0,0,'','','National-park fee applies; boat fare extra',5.0,4.9,7.6786,98.7657,'Ko Phi Phi Leh, Krabi','https://www.tourismthailand.org/Destinations/Provinces/Krabi/344',0.99,'2026-10-01 16:22:00',NULL,'attraction',NULL,'mid','na','own','2026-10-01 16:22:00','partial','TAT highlights Hat Maya/Maya Bay as a flagship Krabi attraction. Access rules, swimming restrictions and seasonal conservation closures change, so fixed hours are intentionally not hard-coded as verified.','2026-10-01'),
('200091','2005','Bamboo Island','Ko Mai Phai / Bamboo Island','Small sandy island north of Phi Phi Don, popular for snorkeling and beach stops on Phi Phi tours.','2-3 hours','Morning','Visit early before shared speedboat tours cluster around the beach.','Boat tour required','Krabi',0,1,'','6:05 PM','National-park fee and boat fare apply',4.8,4.7,7.8168,98.7966,'Hat Noppharat Thara–Mu Ko Phi Phi National Park, Krabi',NULL,0.9,'2026-10-01 16:22:00',NULL,'attraction',NULL,'mid','na','own','2026-10-01 16:22:00','partial','Bamboo Island is an established Phi Phi marine-park stop. Current access depends on park conservation controls and sea conditions; no single authoritative daily timetable was captured in this pass.','2026-10-01'),
('200092','2005','Khao Khanab Nam','Khao Khanap Nam','Pair of limestone hills flanking the Krabi River, regarded as a symbol of Krabi and reached by long-tail boat.','1-2 hours','Morning','Hire a long-tail boat from Chao Fa Pier and combine with mangroves and Ko Klang.','','Krabi',0,0,'','','TAT example long-tail boat trip THB 300 per trip; current operator rates may differ',4.7,4.7,8.0678,98.9213,'Krabi River, Pak Nam, Mueang Krabi, Krabi','https://www.tourismthailand.org/Trip-Planner/Suggestion-Detail/recommended-route-for-one-day',0.88,'2026-10-01 16:22:00',NULL,'attraction',NULL,'budget','na','own','2026-10-01 16:22:00','verified','TAT calls Khao Khanap Nam the symbol of Krabi, describes its limestone caves and states it is about 15 minutes by long-tail boat from Chao Fa Pier. TAT gives THB 300 as an example boat hire in its itinerary text.','2026-10-01'),
('200093','2005','Ko Klang Community','Ko Klang','Traditional Muslim island community opposite Krabi Town, known for rice fields, local crafts, fishing and community-based tourism.','Half day','Morning','Visit respectfully with a community guide or local transport and combine with Khao Khanab Nam.','','Krabi',0,0,'','','Community access free; local transport, guide and activities extra',4.5,4.7,8.0540,98.9395,'Ko Klang, Khlong Prasong, Mueang Krabi, Krabi','https://www.tourismthailand.org/Trip-Planner/Suggestion-Detail/recommended-route-for-one-day',0.83,'2026-10-01 16:22:00',NULL,'attraction',NULL,'budget','na','own','2026-10-01 16:22:00','verified','TAT includes Ko Klang in its recommended one-day Krabi route together with Khao Khanap Nam and Krabi Walking Street.','2026-10-01'),
('200094','2005','Wat Tham Suea','Tiger Cave Temple','Forest temple complex northeast of Krabi Town, famous for its steep summit staircase, golden Buddha and panoramic karst views.','2-3 hours','Early Morning','Carry water and climb before midday heat; monkeys may be present around lower areas.','','Krabi',1,1,'6:15 AM','6:05 PM','Free / donation-supported',4.9,4.8,8.1269,98.9249,'Krabi Noi, Mueang Krabi, Krabi 81000',NULL,0.95,'2026-10-01 16:22:00',NULL,'attraction',NULL,'budget','na','own','2026-10-01 16:22:00','partial','Wat Tham Suea is one of Krabi’s best-known religious/viewpoint attractions. Current practical access is early morning through evening, but no sufficiently authoritative official daily visitor timetable was captured in this pass.','2026-10-01'),
('200095','2005','Emerald Pool','Sa Morakot','Natural emerald-green freshwater pool in lowland forest near Khlong Thom, with trails continuing toward the Blue Pool headwater.','2-3 hours','Morning','Arrive early for clearer water and lighter crowds; swimming is allowed in Emerald Pool but not Blue Pool.','','Krabi',0,0,'','','TAT Japan currently lists THB 400 admission',4.9,4.8,7.9234,99.2682,'Khlong Thom Nuea, Khlong Thom, Krabi 81120','https://www.thailandtravel.or.jp/emerald-pool-krabi/',0.95,'2026-10-01 16:22:00',NULL,'attraction',NULL,'mid','na','own','2026-10-01 16:22:00','verified','Tourism Authority of Thailand Japan currently lists Emerald Pool open 9:00 AM-5:00 PM and admission THB 400. TAT describes the natural pool and the Blue Pool headwater beyond it.','2026-10-01'),
('200096','2005','Hot Spring Waterfall Khlong Thom','Namtok Ron','Natural warm mineral cascade in the Khlong Thom forest forming terraced soaking pools above the stream.','1.5-2 hours','Morning','Combine with Emerald Pool and avoid the hottest midday hours.','','Krabi',0,0,'','','Paid local attraction; current exact foreign fee should be confirmed onsite',4.7,4.7,7.9343,99.2086,'Khlong Thom Nuea, Khlong Thom, Krabi 81120',NULL,0.88,'2026-10-01 16:22:00',NULL,'attraction',NULL,'mid','na','own','2026-10-01 16:22:00','verified','TAT Green Tourism material describes Hot Spring Waterfall as a natural warm mineral cascade in Khlong Thom and lists daily opening 8:00 AM-6:00 PM.','2026-10-01'),
('200097','2005','Tha Pom Khlong Song Nam','Tha Pom Klong Song Nam','Mangrove and freshwater ecosystem where clear inland water mixes with tidal seawater, crossed by a raised nature walkway.','1.5-2 hours','Morning','Water clarity and salinity change with the tide; check local tide timing for the best visual effect.','','Krabi',0,0,'','','Local conservation-area fee may apply; confirm onsite',4.7,4.7,8.2145,98.7828,'Khao Khram, Mueang Krabi, Krabi','https://www.tourismthailand.org/Trip-Planner/Suggestion-Detail/ao-railay-railay-bay-tham-phra-nang-beach-phra-nang-cave-beach-thale-waek-separated-sea-ko-po-da-khao-khanap-nam-viewpoint-tha-pom-khlang-cave',0.88,'2026-10-01 16:22:00',NULL,'attraction',NULL,'budget','na','own','2026-10-01 16:22:00','verified','TAT’s official Krabi itinerary includes Tha Pom Klong Song Nam and describes it as a nature/research area in Khao Khram.','2026-10-01'),
('200098','2005','Than Bok Khorani National Park','Than Bok Khorani National Park','Limestone, rainforest, mangrove and marine national park centered on Ao Luek and extending to islands including Ko Hong.','3-5 hours','Morning','The mainland park and offshore islands are different experiences; confirm boat and weather conditions for marine sections.','','Krabi',0,0,'','','Foreign adult THB 300; child THB 100 per TAT',4.7,4.7,8.3814,98.7379,'2/2 Moo 2, Ao Luek Tai, Ao Luek, Krabi 81110','https://thai.tourismthailand.org/Attraction/%E0%B8%AD%E0%B8%B8%E0%B8%97%E0%B8%A2%E0%B8%B2%E0%B8%99%E0%B9%81%E0%B8%AB%E0%B9%88%E0%B8%87%E0%B8%8A%E0%B8%B2%E0%B8%95%E0%B8%B4%E0%B8%98%E0%B8%B2%E0%B8%A3%E0%B9%82%E0%B8%9A%E0%B8%81%E0%B8%82%E0%B8%A3%E0%B8%93%E0%B8%B5',0.89,'2026-10-01 16:22:00',NULL,'attraction',NULL,'mid','na','own','2026-10-01 16:22:00','verified','TAT official listing describes the park’s limestone, evergreen, mangrove and marine ecosystems and lists foreign admission THB 300 adult / THB 100 child.','2026-10-01'),
('200099','2005','Ao Thalane','Ao Thalane Mangroves','Quiet mangrove bay northwest of Krabi known for sea kayaking through limestone channels and narrow forest waterways.','Half day','Morning','Book a reputable kayak operator and go around high tide for easier navigation through narrower channels.','Kayak booking recommended','Krabi',0,0,'','','Kayak tours vary by operator',4.7,4.7,8.1715,98.7518,'Khao Thong, Mueang Krabi, Krabi',NULL,0.87,'2026-10-01 16:22:00',NULL,'attraction',NULL,'mid','na','own','2026-10-01 16:22:00','partial','Ao Thalane is an established Krabi mangrove-kayaking area. No single public attraction gate or authoritative opening schedule applies; access depends on tides and operator schedules.','2026-10-01'),
('200100','2005','Khlong Root (Clear Water Canal)','Nong Thale Clear Water Canal','Clear freshwater canal and wetland near Nong Thale used for kayaking among submerged roots, forest and calm water.','2-3 hours','Morning','Visit early for calmer water and better light; local kayak rentals operate independently.','','Krabi',0,0,'','','Kayak rental/activity fee varies by local operator',4.5,4.7,8.1012,98.7702,'Nong Thale, Mueang Krabi, Krabi',NULL,0.82,'2026-10-01 16:22:00',NULL,'attraction',NULL,'budget','na','own','2026-10-01 16:22:00','partial','Khlong Root/Nong Thale is a recognized local clear-water kayaking destination, but no authoritative public timetable/fee source was captured in this verification pass.','2026-10-01'),
('200101','2005','Khao Ngon Nak Nature Trail','Dragon Crest / Khao Ngon Nak','Steep 3.7-km one-way forest trail to a high viewpoint over Tubkaek, limestone hills and offshore islands.','4-5 hours','Early Morning','Wear proper hiking shoes, carry water and start early enough to return before the trail closes.','','Krabi',1,1,'6:15 AM','6:05 PM','No separate trail fee clearly published by TAT; check park checkpoint',4.8,4.8,8.0925,98.7490,'Nong Thale, Mueang Krabi, Krabi 81000','https://www.thailandtravel.or.jp/khao-ngon-nak-nature-trail/',0.92,'2026-10-01 16:22:00',NULL,'attraction',NULL,'budget','na','own','2026-10-01 16:22:00','verified','TAT Japan lists the Khao Ngon Nak trail as 3.7 km one way, around two hours up, with opening hours 8:30 AM-5:00 PM.','2026-10-01'),
('200102','2005','Khao Phanom Bencha National Park','Khao Phanom Bencha National Park','Rainforest national park north of Krabi Town with Huai To Waterfall, caves, nature trails and seasonal summit trekking.','3-5 hours','Morning','Use the visitor-center area for Huai To Waterfall unless you have confirmed a seasonal summit trek with park staff.','','Krabi',0,0,'','','Foreign adult THB 100; child THB 50; car THB 30 (current 2026 park data)',4.6,4.6,8.2406,98.9136,'Thap Prik, Mueang Krabi, Krabi','https://booking.dnp.go.th/',0.86,'2026-10-01 16:22:00',NULL,'attraction',NULL,'budget','na','own','2026-10-01 16:22:00','partial','Current 2026 park-reference data lists daily 8:30 AM-4:30 PM, foreign THB 100 adult / 50 child and car THB 30. The summit route is seasonal and can close separately, so status is partial pending direct DNP page capture.','2026-10-01'),
('200103','2005','Krabi Walking Street','Krabi Weekend Night Market','Weekend walking street on Maharaj Road with street food, crafts, souvenirs and live performances.','2-3 hours','Evening','Go near opening time for easier browsing and stay for dinner.','','Krabi',0,0,'','','Free entry; food/shopping extra',4.7,4.6,8.0637,98.9168,'Maharaj Road, Pak Nam, Mueang Krabi, Krabi','https://thai.tourismthailand.org/Destinations/Provinces/%E0%B8%81%E0%B8%A3%E0%B8%B0%E0%B8%9A%E0%B8%B5%E0%B9%88/344',0.87,'2026-10-01 16:22:00',NULL,'attraction','Street Food','budget','veg-options','own','2026-10-01 16:22:00','verified','TAT Krabi destination page states Walking Street is held on Maharaj Road every Friday, Saturday and Sunday from 5:00 PM-10:00 PM.','2026-10-01'),
('200104','2005','Chao Fah Night Market','Chao Fah Pier Night Market','Evening food market around Chao Fah pier serving inexpensive Thai dishes, seafood, drinks and snacks.','1-2 hours','Evening','Ideal for a casual dinner after a river or town day.','','Krabi',0,0,'','','Free entry; food purchases extra',4.5,4.5,8.0648,98.9200,'Chao Fah Pier area, Pak Nam, Mueang Krabi, Krabi','https://thai.tourismthailand.org/Destinations/Provinces/%E0%B8%81%E0%B8%A3%E0%B8%B0%E0%B8%9A%E0%B8%B5%E0%B9%88/344',0.8,'2026-10-01 16:22:00',NULL,'attraction','Street Food','budget','veg-options','own','2026-10-01 16:22:00','verified','TAT Krabi destination page states the Chao Fah pier night market opens daily from 5:00 PM-9:30 PM.','2026-10-01'),
('200105','2005','Susan Hoi (75 Million-Year-Old Shell Cemetery)','Fossil Shell Beach','Geological coastal site with compacted fossil-shell slabs exposed along the shore near Ban Laem Pho.','1-1.5 hours','Morning','Visit near lower tide for better shoreline visibility and combine with Ao Nang/Railay on the same side of town.','','Krabi',0,0,'','','Protected-site fee may apply; confirm current ticket onsite',4.3,4.2,8.0000,98.9065,'Sai Thai, Mueang Krabi, Krabi','https://www.tourismthailand.org/Trip-Planner/Suggestion-Detail/krabi-trang-4-days',0.73,'2026-10-01 16:22:00',NULL,'attraction',NULL,'budget','na','own','2026-10-01 16:22:00','verified','TAT includes the 75 Million-year-old Shell Cemetery in its official Krabi trip planner and province highlights.','2026-10-01'),
('200106','2005','Wat Kaew Korawaram','Wat Kaew Korawaram','White hilltop Buddhist temple in central Krabi Town reached by a broad staircase, offering a quiet urban religious stop.','45-60 minutes','Morning','Dress respectfully and combine with Krabi Walking Street and the riverfront.','','Krabi',0,0,'','','Free / donation-supported',4.4,4.4,8.0630,98.9143,'Pak Nam, Mueang Krabi, Krabi 81000',NULL,0.76,'2026-10-01 16:22:00',NULL,'attraction',NULL,'budget','na','own','2026-10-01 16:22:00','partial','Wat Kaew Korawaram is a well-established central Krabi Town temple. A reliable current official visitor-hours page was not captured; practical temple access is daytime.','2026-10-01'),
('200107','2005','Ao Nang Landmark Night Market','Ao Nang Landmark Night Market','Large evening market near Noppharat Thara with street food, seafood, souvenir stalls and entertainment.','2-3 hours','Evening','Useful dinner stop when staying in Ao Nang; arrive before peak dinner crowds.','','Krabi',0,0,'','','Free entry; vendor purchases extra',4.5,4.5,8.0476,98.8128,'Ao Nang, Mueang Krabi, Krabi 81180',NULL,0.8,'2026-10-01 16:22:00',NULL,'attraction','Street Food','budget','veg-options','own','2026-10-01 16:22:00','partial','Ao Nang Landmark is a major local night market near Noppharat Thara. Current listings consistently show evening operation, but no sufficiently authoritative official schedule was captured in this pass.','2026-10-01'),
('200108','2005','Ruenmai Krabi','Ruenmai Krabi','Garden-style restaurant in Sai Thai specializing in Southern Thai dishes and regional ingredients.','1-2 hours','Dinner','Reserve in peak season and ask for spice level if you are sensitive to southern Thai heat.','Reservation recommended','Krabi',0,0,'','','Mid-range Southern Thai; menu varies',4.7,4.7,8.0655,98.8765,'117 Moo 3, Sai Thai, Mueang Krabi, Krabi 81000','https://www.facebook.com/ruenmaikrabirestuarant/',0.87,'2026-10-01 16:22:00',NULL,'restaurant','Southern Thai','mid','veg-options','own','2026-10-01 16:22:00','verified','Tourism Authority of Thailand Japan lists Ruenmai Krabi as a Southern Thai restaurant with opening 10:30 AM-3:00 PM and 5:00-9:30 PM, at Sai Thai, Mueang Krabi.','2026-10-01'),
('200109','2005','Lae Lay Grill','Lae Lay Grill','Hilltop Ao Nang seafood restaurant with broad sea-and-island sunset views.','1.5-2 hours','Sunset','Reserve a view table in advance for sunset; free-transfer availability may depend on current restaurant policy.','Reservation recommended','Krabi',0,1,'','6:05 PM','TAT lists approximately THB 150-2,000 depending on dish',4.6,4.6,8.0388,98.8217,'89 Moo 3, Ao Nang, Mueang Krabi, Krabi 81000','https://www.laelaygrill.com/',0.85,'2026-10-01 16:22:00',NULL,'restaurant','Seafood / Thai','premium','veg-options','own','2026-10-01 16:22:00','verified','Official Lae Lay Grill site lists daily opening 11:00 AM-10:00 PM; TAT Japan independently lists the same hours and a broad THB 150-2,000 price range.','2026-10-01'),
('200110','2005','KoDam Kitchen','KoDam Kitchen','Casual Ao Nang Thai and seafood restaurant known for local-style dishes, curries and desserts in a garden-like setting.','1-1.5 hours','Dinner','Walk in early during peak season or contact the restaurant for large groups.','','Krabi',0,0,'','','Budget to mid-range Thai/seafood',4.6,4.6,8.0402,98.8205,'155/7 Khlong Hang Road, Ao Nang, Mueang Krabi, Krabi 81180','https://kodamkitchen.com/',0.83,'2026-10-01 16:22:00',NULL,'restaurant','Thai / Seafood','mid','veg-options','own','2026-10-01 16:22:00','verified','Official KoDam Kitchen site lists daily opening 11:00 AM-10:30 PM, address 155/7 Khlong Hang Road, and Thai/seafood as recommended cuisine.','2026-10-01');
