INSERT INTO festivals (id, state_id, city_id, place_id, festival_name, timing_label, lunar_note, duration_label, description, source, updated_at) VALUES
(300013,9005,2005,NULL,'Krabi Pride 2026','20 June 2026','Dated 2026 event; future recurrence must be refreshed','1 day','TAT Newsroom listed Krabi Pride 2026 for 20 June 2026 as part of Thailand Pride Month programming.','own','2026-10-01 16:22:00'),
(300014,9005,2005,200103,'Krabi Weekend Walking Street','Friday-Sunday, year-round','Weekly recurring market rather than lunar festival','Weekly','Recurring Maharaj Road walking street with food, shopping and local performances; TAT lists 5:00 PM-10:00 PM Friday-Sunday.','own','2026-10-01 16:22:00'),
(300015,9005,2005,NULL,'Krabi Boek Fa Andaman / Andaman tourism-season events','Typically early high season','Dates vary yearly and should be refreshed','Varies','Krabi hosts seasonal tourism-opening and Andaman cultural/event programming around the start of the dry/high season; exact current-year branding and dates require annual verification.','own','2026-10-01 16:22:00');
INSERT INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score, created_at, google_place_id, category, cuisine, price_band, veg_flag, source, updated_at, verification_status, verification_notes, verified_at) VALUES
('200111','2006','Chaweng Beach','Chaweng Beach','Ko Samui’s best-known resort beach, with a long sweep of white sand, swimming, restaurants, nightlife and easy access to island services.','3-5 hours','Morning','The central stretch is busiest; north and south sections are generally calmer. Follow sea-condition and flag guidance before swimming.','','Surat Thani',1,0,'6:05 AM','','Free public beach; activities extra',5.0,4.6,9.5284,100.0624,'Chaweng, Bo Phut, Ko Samui, Surat Thani 84320','https://www.tourismthailand.org/Destinations/Provinces/Ko-Samui/360',0.98,'2026-10-01 16:22:00',NULL,'attraction',NULL,'budget','na','own','2026-10-01 16:22:00','verified','TAT names Chaweng Beach as a principal Ko Samui highlight and describes Samui as a beach destination with extensive visitor services. Chaweng is an open public beach rather than a ticketed attraction.','2026-10-01'),
('200112','2006','Lamai Beach','Lamai Beach','Major east-coast beach with a broad sandy bay, swimming, resorts and a more relaxed center than Chaweng.','3-5 hours','Morning','Combine the beach with Hin Ta–Hin Yai and Wat Ratchathammaram in the Lamai area.','','Surat Thani',1,0,'6:05 AM','','Free public beach; activities extra',4.9,4.7,9.4662,100.0457,'Maret, Ko Samui, Surat Thani 84310','https://www.tourismthailand.org/Destinations/Provinces/Ko-Samui/360',0.95,'2026-10-01 16:22:00',NULL,'attraction',NULL,'budget','na','own','2026-10-01 16:22:00','verified','TAT explicitly highlights Lamai Beach among Ko Samui’s major beaches. Public beach access is unticketed.','2026-10-01'),
('200113','2006','Bo Phut Beach & Fisherman’s Village','Bophut Fisherman’s Village','Historic beachfront district with old Chinese-style shophouses, restaurants, boutique lodging and a walkable village atmosphere.','2-4 hours','Late Afternoon','Come before sunset, stay for dinner, and combine with the evening market when it is operating.','','Surat Thani',0,1,'','6:10 PM','Free public district; shopping and dining extra',4.9,4.8,9.5596,100.0316,'Bo Phut Beach Road, Bo Phut, Ko Samui, Surat Thani 84320','https://www.tourismthailand.org/Destinations/Provinces/Ko-Samui/360',0.96,'2026-10-01 16:22:00',NULL,'attraction',NULL,'budget','na','own','2026-10-01 16:22:00','verified','TAT describes Bo Phut as an old-world area of Ko Samui with converted Chinese shophouses. The village and beachfront streets are public and do not have a single gate timetable.','2026-10-01'),
('200114','2006','Mae Nam Beach','Maenam Beach','Long north-coast beach with a quieter local-resort feel and views toward Ko Pha-ngan.','2-4 hours','Morning','Good choice for a calmer beach day; conditions are often gentler than the busiest east-coast stretches.','','Surat Thani',1,1,'6:05 AM','6:10 PM','Free public beach',4.6,4.6,9.5737,99.9965,'Mae Nam, Ko Samui, Surat Thani 84330',NULL,0.85,'2026-10-01 16:22:00',NULL,'attraction',NULL,'budget','na','own','2026-10-01 16:22:00','partial','Mae Nam is an established north-coast Samui beach. No formal admission or authoritative opening timetable applies; beach access remains condition-dependent.','2026-10-01'),
('200115','2006','Choeng Mon Beach','Choeng Mon Beach','Compact northeast-coast bay popular with families and resort guests, with shallow water in calmer conditions.','2-4 hours','Morning','Check tide depth before swimming and combine with Wat Plai Laem and Big Buddha.','','Surat Thani',1,0,'6:05 AM','','Free public beach',4.6,4.6,9.5718,100.0832,'Bo Phut, Ko Samui, Surat Thani 84320',NULL,0.85,'2026-10-01 16:22:00',NULL,'attraction',NULL,'budget','na','own','2026-10-01 16:22:00','partial','Choeng Mon is a well-established northeast Samui beach. It is open-access with no authoritative gate timetable.','2026-10-01'),
('200116','2006','Taling Ngam Beach','Taling Ngam Beach','Quiet southwest-coast beach facing the Ang Thong archipelago, valued for uncrowded shoreline and sunset views.','2-4 hours','Sunset','Plan transport because the area is less dense with taxis and nightlife than Chaweng or Lamai.','','Surat Thani',0,1,'','6:10 PM','Free public beach',4.6,4.7,9.4540,99.9348,'Taling Ngam, Ko Samui, Surat Thani 84140','https://www.tourismthailand.org/Destinations/Provinces/Ko-Samui/360',0.87,'2026-10-01 16:22:00',NULL,'attraction',NULL,'budget','na','own','2026-10-01 16:22:00','verified','TAT lists Taling Ngam among the island’s notable beaches and specifically notes Samui’s quieter resort beaches.','2026-10-01'),
('200117','2006','Lipa Noi Beach','Lipa Noi Beach','West-coast sandy beach near Nathon and the ferry corridor, known for shallow water and sunset views.','2-4 hours','Sunset','A practical sunset stop if staying on the west side or arriving via Raja Ferry.','','Surat Thani',0,1,'','6:10 PM','Free public beach',4.5,4.6,9.4939,99.9326,'Lipa Noi, Ko Samui, Surat Thani 84140',NULL,0.82,'2026-10-01 16:22:00',NULL,'attraction',NULL,'budget','na','own','2026-10-01 16:22:00','partial','Lipa Noi is an established public west-coast beach. No formal opening timetable or admission applies.','2026-10-01'),
('200118','2006','Wat Phra Yai','Big Buddha Temple','Hilltop temple on Ko Fan dominated by a large golden seated Buddha and reached by a naga-lined staircase.','1-1.5 hours','Morning','Dress modestly, remove shoes where required and pair with Wat Plai Laem nearby.','','Surat Thani',1,1,'6:05 AM','6:10 PM','Free / donation-supported',4.9,4.7,9.5708,100.0605,'Bo Phut, Ko Samui, Surat Thani 84320',NULL,0.94,'2026-10-01 16:22:00',NULL,'attraction',NULL,'budget','na','own','2026-10-01 16:22:00','partial','Big Buddha/Wat Phra Yai is one of Samui’s best-known religious landmarks. Current visitor listings generally show daytime access, but a sufficiently authoritative temple timetable was not captured in this pass.','2026-10-01'),
('200119','2006','Wat Plai Laem','Wat Plai Laem','Colorful lakeside Buddhist temple complex known for a many-armed Guanyin image, large Budai figure and ornate Thai-Chinese religious architecture.','1-1.5 hours','Morning','Visit respectfully and avoid feeding lake fish unless using approved temple food.','','Surat Thani',0,0,'','','Free / donation-supported',4.8,4.7,9.5716,100.0669,'Road 4171, Bo Phut, Ko Samui, Surat Thani 84320',NULL,0.91,'2026-10-01 16:22:00',NULL,'attraction',NULL,'budget','na','own','2026-10-01 16:22:00','partial','Wat Plai Laem is a prominent northeast Ko Samui temple complex. Exact current visitor hours are not supported by a sufficiently authoritative first-party page in this pass.','2026-10-01'),
('200120','2006','Wat Ratchathammaram','Red Temple / Wat Sila Ngu','Distinctive terracotta-red Buddhist temple near Lamai featuring elaborate relief carvings and a coastal setting.','45-60 minutes','Morning','Combine with Lamai Beach and Hin Ta–Hin Yai; dress respectfully.','','Surat Thani',0,0,'','','Free / donation-supported',4.6,4.7,9.4512,100.0318,'Maret, Ko Samui, Surat Thani 84310',NULL,0.84,'2026-10-01 16:22:00',NULL,'attraction',NULL,'budget','na','own','2026-10-01 16:22:00','partial','Wat Ratchathammaram/Wat Sila Ngu is an established Lamai-area temple. No authoritative current daily visitor timetable was captured in this pass.','2026-10-01'),
('200121','2006','Wat Khunaram','Wat Khunaram (Mummified Monk)','Active Buddhist temple best known for the preserved seated body of monk Luang Pho Daeng displayed in meditation posture.','45-60 minutes','Morning','Treat the site as a religious place rather than a curiosity; dress and behave respectfully.','','Surat Thani',0,0,'','','Free / donation-supported',4.5,4.4,9.4502,100.0011,'Na Mueang, Ko Samui, Surat Thani 84140',NULL,0.8,'2026-10-01 16:22:00',NULL,'attraction',NULL,'budget','na','own','2026-10-01 16:22:00','partial','Wat Khunaram is a long-established Samui religious site associated with Luang Pho Daeng. Reliable current first-party opening hours were not captured, so the visitor window is marked partial.','2026-10-01'),
('200122','2006','Guan Yu Koh Samui Shrine','Guan Yu Shrine','Large Chinese shrine and cultural landmark in Hua Thanon associated with Samui’s Hainanese Chinese community.','45-90 minutes','Morning','Combine with Hua Thanon village and southern-island food stops.','','Surat Thani',0,0,'','','Free / donation-supported',4.5,4.5,9.4317,100.0227,'Hua Thanon, Maret, Ko Samui, Surat Thani 84310',NULL,0.8,'2026-10-01 16:22:00',NULL,'attraction',NULL,'budget','na','own','2026-10-01 16:22:00','partial','Guan Yu Shrine is a recognized Chinese cultural and religious site in Hua Thanon. Current authoritative opening hours/fees were not captured.','2026-10-01'),
('200123','2006','Hin Ta and Hin Yai','Grandfather and Grandmother Rocks','Distinctive naturally weathered granite formations on the Lamai coast, surrounded by small stalls and sea viewpoints.','45-90 minutes','Morning','Visit outside peak tour-bus times and use caution on wet coastal rocks.','','Surat Thani',0,1,'','6:10 PM','Free public rock formation; parking/private access charges may apply',4.8,4.5,9.4519,100.0397,'Maret, Ko Samui, Surat Thani 84310','https://www.tourismthailand.org/Destinations/Provinces/Kanchanaburi/354',0.88,'2026-10-01 16:22:00',NULL,'attraction',NULL,'budget','na','own','2026-10-01 16:22:00','verified','TAT’s Surat Thani destination material specifically names Hin Ta and Hin Yai at Lamai as a natural attraction. The formations themselves are an open coastal site.','2026-10-01'),
('200124','2006','Na Muang Waterfall 1','Na Muang Waterfall','Accessible lower Na Muang waterfall cascading roughly 30 metres over granite into a natural pool in Samui’s interior.','1-2 hours','Morning','The flow is strongest in the wetter season; rocks can be slippery and swimming should follow local safety conditions.','','Surat Thani',0,0,'','','Free entry per Department of Tourism directory',4.8,4.7,9.4667,99.9846,'Na Mueang, Ko Samui, Surat Thani 84140','https://www.thailandtourismdirectory.go.th/en/attraction/2127',0.91,'2026-10-01 16:22:00',NULL,'attraction',NULL,'budget','na','own','2026-10-01 16:22:00','verified','TAT Japan lists Na Muang Waterfall open 8:00 AM-6:00 PM. Thailand Digital Tourism Center identifies it as a roughly 30-metre waterfall and lists no admission charge.','2026-10-01'),
('200125','2006','Na Muang Waterfall 2','Na Muang 2 Waterfall','Higher and more strenuous upper waterfall reached via a jungle ascent above the lower Na Muang area.','2-3 hours','Morning','Wear good footwear and avoid the upper trail during heavy rain or when rocks are slick.','','Surat Thani',0,0,'','','Access commonly free; private parking/activity operators may charge separately',4.6,4.6,9.4737,99.9802,'Na Mueang, Ko Samui, Surat Thani 84140',NULL,0.84,'2026-10-01 16:22:00',NULL,'attraction',NULL,'budget','na','own','2026-10-01 16:22:00','partial','Current Samui tourism material describes Na Muang as a two-tier waterfall system, with the higher tier requiring a more demanding hike. No separate authoritative timetable for Na Muang 2 was captured.','2026-10-01'),
('200126','2006','Hin Lad Waterfall','Hin Lat Waterfall','Forested waterfall near Nathon reached by a walking trail beside streams and pools.','2-3 hours','Morning','Wear hiking shoes and expect more water during the rainy season; avoid slippery rocks after storms.','','Surat Thani',0,0,'','','No charge per Thailand Digital Tourism Center',4.4,4.5,9.5209,99.9568,'Ang Thong, Ko Samui, Surat Thani 84140','https://www.thailandtourismdirectory.go.th/en/attraction/2142',0.78,'2026-10-01 16:22:00',NULL,'attraction',NULL,'budget','na','own','2026-10-01 16:22:00','verified','Thailand Digital Tourism Center confirms Hin Lad Waterfall in Ko Samui and lists no admission charge. Its rendered hours are malformed, so only identity and free admission are treated as verified.','2026-10-01'),
('200127','2006','Secret Buddha Garden','Tarnim Magic Garden','Private hillside sculpture garden hidden in Samui’s interior, with statues, small streams and lush tropical vegetation.','1-1.5 hours','Morning','The mountain road is steep; use a suitable vehicle or guided island tour if uncomfortable driving.','','Surat Thani',0,0,'','','Private-site admission commonly charged; confirm current fee onsite',4.5,4.5,9.4786,99.9943,'Na Mueang, Ko Samui, Surat Thani',NULL,0.8,'2026-10-01 16:22:00',NULL,'attraction',NULL,'budget','na','own','2026-10-01 16:22:00','partial','Secret Buddha Garden/Tarnim Magic Garden is a well-established private hillside attraction, but current authoritative fee/hours information was not captured in this pass.','2026-10-01'),
('200128','2006','Lad Koh Viewpoint','Lad Koh / Chaweng Viewpoint','Roadside coastal viewpoint between Chaweng and Lamai overlooking the Gulf and rocky shoreline.','20-40 minutes','Morning','Stop only in designated parking areas; traffic on the ring road can be fast.','','Surat Thani',1,1,'6:05 AM','6:10 PM','Free public viewpoint',4.6,4.5,9.4925,100.0642,'Route 4169 between Chaweng and Lamai, Ko Samui',NULL,0.82,'2026-10-01 16:22:00',NULL,'attraction',NULL,'budget','na','own','2026-10-01 16:22:00','partial','Lad Koh is a recognized public coastal viewpoint on the Samui ring road. No formal gate timetable applies; practical use is daylight/evening.','2026-10-01'),
('200129','2006','Overlap Stone','Overlap Stone Viewpoint','Large balancing boulder viewpoint above Lamai with elevated views over the southeast coast.','1-1.5 hours','Morning','Access roads are steep and there are multiple similarly named private viewpoints; confirm the exact site before driving.','','Surat Thani',0,1,'','6:10 PM','Private viewpoint fee varies; confirm onsite',4.4,4.4,9.4570,100.0148,'Maret hills, Ko Samui, Surat Thani',NULL,0.77,'2026-10-01 16:22:00',NULL,'attraction',NULL,'budget','na','own','2026-10-01 16:22:00','partial','Multiple private Overlap Stone viewpoints/listings exist in the Lamai hills, with changing access roads and fees. Keep this record partial until a specific operator/site is selected.','2026-10-01'),
('200130','2006','Mu Ko Ang Thong National Marine Park','Ang Thong Marine National Park','Protected Gulf of Thailand archipelago of limestone islands, beaches, lagoons, kayaking and viewpoints, commonly visited by day boat from Samui.','Full day','Morning','Book with a licensed operator and confirm seasonal park opening plus sea conditions before departure.','Boat tour required','Surat Thani',0,0,'','','Special-area foreign fee THB 300 adult / THB 150 child; boat tour extra',5.0,4.9,9.6300,99.6800,'Mu Ko Ang Thong National Park, Surat Thani','https://www.tourismthailand.org/Destinations/Provinces/Ko-Samui/360',0.99,'2026-10-01 16:22:00',NULL,'attraction',NULL,'premium','na','own','2026-10-01 16:22:00','verified','TAT describes Ang Thong National Marine Park as an archipelago of more than 80 islands and a major kayak/day-trip destination from Ko Samui. DNP/TAT special-area fee schedule lists foreign visitors at THB 300 adult / THB 150 child for Ko Wua Ta Lap and Ko Mae Ko areas.','2026-10-01'),
('200131','2006','Ko Mae Ko and Emerald Lake','Mae Ko Island / Talay Nai','Ang Thong island famous for a steep stair viewpoint over the enclosed saltwater lagoon known as Talay Nai or Emerald Lake.','1.5-2 hours','Morning','The stair climb is steep; footwear with grip is better than flip-flops.','Boat tour required','Surat Thani',0,0,'','','Covered by Ang Thong special-area national-park fee; boat extra',4.9,4.9,9.6642,99.6630,'Mu Ko Ang Thong National Park, Surat Thani',NULL,0.95,'2026-10-01 16:22:00',NULL,'attraction',NULL,'premium','na','own','2026-10-01 16:22:00','verified','DNP/TAT special-area fee notice specifically identifies Ko Mae Ko within Mu Ko Ang Thong National Park. Access is park- and boat-controlled.','2026-10-01'),
('200132','2006','Ko Wua Ta Lap Viewpoint','Wua Ta Lap Island Viewpoint','Steep national-park trail on the main Ang Thong visitor island leading to a panoramic viewpoint over the archipelago.','2-3 hours','Morning','The climb is steep and exposed in sections; carry water and follow ranger instructions.','Boat tour required','Surat Thani',0,0,'','','Covered by Ang Thong special-area national-park fee; boat extra',4.9,4.9,9.6276,99.6755,'Mu Ko Ang Thong National Park, Surat Thani',NULL,0.95,'2026-10-01 16:22:00',NULL,'attraction',NULL,'premium','na','own','2026-10-01 16:22:00','verified','DNP/TAT special-area fee notice specifically identifies Ko Wua Ta Lap within Mu Ko Ang Thong National Park. Trail availability depends on weather and park controls.','2026-10-01'),
('200133','2006','Ko Madsum','Pig Island / Koh Madsum','Small island south of Samui known for a sandy beach and free-roaming pigs, usually paired with snorkeling stops.','3-5 hours','Morning','Use a responsible licensed boat operator and avoid feeding animals inappropriate food.','Boat transfer required','Surat Thani',0,1,'','6:10 PM','Island/boat package prices vary by operator',4.6,4.5,9.4014,99.9783,'Ko Madsum, Surat Thani',NULL,0.83,'2026-10-01 16:22:00',NULL,'attraction',NULL,'mid','na','own','2026-10-01 16:22:00','partial','Ko Madsum is a popular south-Samui day-trip island. There is no single authoritative public ticket/timetable because transport and beach services are operator-dependent.','2026-10-01'),
('200134','2006','Ko Taen','Koh Tan','Quiet island south of Samui with coral areas, mangroves and village landscapes, often paired with Ko Madsum.','Half day','Morning','Good for a slower boat day; snorkeling visibility depends on weather and tide.','Boat transfer required','Surat Thani',0,1,'','6:10 PM','Boat/snorkeling packages vary by operator',4.5,4.5,9.3860,99.9690,'Ko Taen, Surat Thani',NULL,0.81,'2026-10-01 16:22:00',NULL,'attraction',NULL,'mid','na','own','2026-10-01 16:22:00','partial','Ko Taen is an established island excursion south of Samui. Exact access and activity schedules are operator- and weather-dependent.','2026-10-01'),
('200135','2006','Samui Elephant Sanctuary','Samui Elephant Sanctuary','Rescue-focused elephant sanctuary offering scheduled observation and feeding programs at Bophut and Chaweng Noi locations.','3 hours','Morning','Visits are booking-only; do not arrive without confirmation because the sanctuary does not accept unscheduled guests.','Advance booking required','Surat Thani',0,0,'','','Current low-season 3-hour program THB 2,900 adult / THB 1,400 child 5-11; under 4 free',4.9,4.9,9.5460,100.0150,'Bophut / Chaweng Noi, Ko Samui, Surat Thani','https://www.samuielephantsanctuary.org/tour-details',0.96,'2026-10-01 16:22:00',NULL,'attraction',NULL,'premium','na','own','2026-10-01 16:22:00','verified','Official Samui Elephant Sanctuary site checked 2026-10-01: 3-hour morning and afternoon programs; current promotional price THB 2,900 adult / THB 1,400 child 5-11 through 30 Nov 2026; under 4 free. Booking confirmation required before arrival.','2026-10-01'),
('200136','2006','Fisherman’s Village Walking Street','Bophut Walking Street Market','Evening market through Fisherman’s Village with street food, clothing, souvenirs and beachfront dining.','2-3 hours','Evening','Friday is the traditional large walking-street night; current market activity also occurs on additional evenings, so check locally.','','Surat Thani',0,0,'','','Free entry; vendor purchases extra',4.8,4.7,9.5602,100.0310,'Bophut Beach Road, Ko Samui, Surat Thani 84320',NULL,0.91,'2026-10-01 16:22:00',NULL,'attraction','Street Food','budget','veg-options','own','2026-10-01 16:22:00','partial','Current sources conflict on schedule: Amazing Thailand describes the traditional Friday walking street 5:00-11:00 PM, while a Sep 2026 visitor guide reports nightly market activity 6:00-10:00 PM. Keep schedule partial and refresh before publishing.','2026-10-01'),
('200137','2006','Central Samui','Central Samui','Large Chaweng shopping and lifestyle complex with retail, restaurants, street-food zones and events.','2-4 hours','Afternoon','Useful as a rainy-day or midday-heat stop and easy to combine with Chaweng Beach.','','Surat Thani',0,0,'','','Free entry; shopping and dining extra',4.5,4.4,9.5307,100.0619,'209, 209/1-209/2 Moo 2, Bo Phut, Ko Samui, Surat Thani 84320','https://www.centralsamui.com/en',0.82,'2026-10-01 16:22:00',NULL,'attraction',NULL,'budget','veg-options','own','2026-10-01 16:22:00','partial','First-party Central sources conflict: Central department-store directory and tourist guide show 10:00 AM-10:00 PM, while Central Pattana branch information shows 11:00 AM-9:00 PM. Location and identity are verified; operating hours should be refreshed before use.','2026-10-01'),
('200138','2006','Coco Tam’s','Coco Tam’s','Popular Bophut beachfront restaurant and bar known for Italian food, pizza, relaxed beach seating and evening atmosphere.','1.5-3 hours','Evening','Arrive before sunset for beach seating; busy nights may require waiting.','','Surat Thani',0,1,'','6:10 PM','Mid to premium; à la carte',4.7,4.6,9.5603,100.0311,'62 Bo Phut, Ko Samui, Surat Thani 84320','https://www.facebook.com/CoCoTams',0.86,'2026-10-01 16:22:00',NULL,'restaurant','Italian / Pizza / Bar','premium','veg-options','own','2026-10-01 16:22:00','verified','Tourism Authority of Thailand Japan lists Coco Tam’s on Bophut Beach, opening 1:00 PM-midnight, and describes its Italian/pizza concept.','2026-10-01'),
('200139','2006','The Jungle Club Restaurant','The Jungle Club','Hillside Chaweng Noi restaurant with sweeping island-and-sea views and a Thai, French, Italian and Mediterranean menu.','1.5-2.5 hours','Sunset','Reserve at least several days ahead for a view table; the steep access road may require the venue transfer.','Advance reservation recommended','Surat Thani',0,1,'','6:10 PM','Mid to premium; à la carte',4.8,4.7,9.4917,100.0467,'Soi Panyadee, Chaweng Noi, Ko Samui, Surat Thani 84320','https://www.jungleclubsamui.com/restaurant/',0.9,'2026-10-01 16:22:00',NULL,'restaurant','Thai / Mediterranean / European','premium','veg-options','own','2026-10-01 16:22:00','verified','Official Jungle Club site lists restaurant opening 8:00 AM-11:00 PM and asks outside guests to reserve at least three days in advance.','2026-10-01'),
('200140','2006','Supattra Thai Dining','Supattra Thai Dining','Small reservation-focused Thai fine-dining restaurant in Bangrak with an open kitchen and changing blackboard menu.','2 hours','Dinner','Reserve because seating is limited and the restaurant operates only Tuesday through Saturday evenings.','Advance reservation recommended','Surat Thani',0,0,'','','Premium Thai fine dining; à la carte',4.8,4.8,9.5616,100.0568,'Bangrak, Bo Phut, Ko Samui, Surat Thani','https://www.supattrathaidining.com/',0.89,'2026-10-01 16:22:00',NULL,'restaurant','Thai Fine Dining','premium','veg-options','own','2026-10-01 16:22:00','verified','Official Supattra Thai Dining site lists opening Tuesday-Saturday 6:00 PM-10:00 PM and closure Sunday-Monday. The restaurant recommends reservations due to limited tables.','2026-10-01');
