CREATE TABLE IF NOT EXISTS festivals (
  id             INTEGER PRIMARY KEY,
  state_id       INTEGER,
  city_id        INTEGER,
  place_id       INTEGER,
  festival_name  TEXT NOT NULL,
  timing_label   TEXT,
  lunar_note     TEXT,
  duration_label TEXT,
  description    TEXT,
  source         TEXT DEFAULT 'own',
  updated_at     TEXT
);




